/**
 * kana-stroke-data.ts — adapter from the reviewed JSON asset to KanaStrokeGuidance.
 *
 * The JSON (src/data/kana-strokes/animcjk-kana.json) is GENERATED by
 * scripts/kana-strokes/convert-animcjk.mjs from vendored AnimCJK SVGs (LGPL-3.0-or-later per
 * file header; commercial-licensing review PENDING) — see
 * docs/implementation/JPN-035-skills-kana-reference.md.
 */
import type { KanaStrokeGuidance, StrokeDataSource } from "./kana-stroke-guidance";
import strokeData from "../../data/kana-strokes/animcjk-kana.json";

type PilotGlyph = Omit<KanaStrokeGuidance, "source" | "assetVersion">;

export const KANA_STROKE_ASSET = strokeData as unknown as {
  assetVersion: number;
  source: StrokeDataSource;
  modifications: string;
  glyphs: PilotGlyph[];
};

export const KANA_STROKE_DATA: Readonly<Record<string, KanaStrokeGuidance>> = Object.fromEntries(
  KANA_STROKE_ASSET.glyphs.map((g) => [
    g.kanaId,
    { ...g, source: KANA_STROKE_ASSET.source, assetVersion: KANA_STROKE_ASSET.assetVersion },
  ]),
);
